  line-height: var(--font-h2-lh);
  font-weight: var(--font-h2-weight);
  letter-spacing: var(--font-h2-tracking);
}
.frame-root .type-h2-emphasized {
  font-size: var(--font-h2-size);
  line-height: var(--font-h2-lh);
  font-weight: var(--font-h2-emphasized-weight);
  letter-spacing: var(--font-h2-tracking);
}
.frame-root .type-body {
  font-size: var(--font-body-size);
  line-height: var(--font-body-lh);
  font-weight: var(--font-body-weight);
  letter-spacing: var(--font-body-tracking);
}
.frame-root .type-detail {
  font-size: var(--font-detail-size);
  line-height: var(--font-detail-lh);
  font-weight: var(--font-detail-weight);
  letter-spacing: var(--font-detail-tracking);
}
.frame-root .type-detail-emphasized {
  font-size: var(--font-detail-size);
  line-height: var(--font-detail-emphasized-lh);
  font-weight: var(--font-detail-emphasized-weight);
  letter-spacing: var(--font-detail-tracking);
}
.frame-root .type-caption {
  font-size: var(--font-caption-size);
  line-height: var(--font-caption-lh);
  font-weight: var(--font-caption-weight);
  letter-spacing: var(--font-caption-tracking);
}
.frame-root .type-footnote {
  font-size: var(--font-footnote-size);
  line-height: var(--font-footnote-lh);
  font-weight: var(--font-footnote-weight);
  letter-spacing: var(--font-footnote-tracking);
}
.frame-root .panel-border {
  border: 1px solid var(--color-card-panel-bg);
}
.dark .frame-root .panel-border, .frame-root.dark .panel-border {
  border-color: var(--color-stroke-outline);
}
.frame-root .status-pending     { --status-bg: rgba(245,158,11,0.15);  --status-fg: #B8541A; }
.frame-root .status-in-progress { --status-bg: rgba(49,113,255,0.1);   --status-fg: #3171FF; }
.frame-root .status-submitted   { --status-bg: rgba(118,82,185,0.15);  --status-fg: #6B54E6; }
.frame-root .status-in-review   { --status-bg: rgba(234,179,8,0.18);   --status-fg: #A87725; }
.frame-root .status-success     { --status-bg: rgba(2,137,1,0.1);      --status-fg: #028901; }
.frame-root .status-failed      { --status-bg: rgba(220,38,38,0.12);   --status-fg: #C93838; }
.frame-root .status-expired     { --status-bg: rgba(107,114,128,0.15); --status-fg: #6B7280; }
.frame-root .status-neutral     { --status-bg: var(--color-bg-hover);  --status-fg: var(--color-text-primary); }
.dark .frame-root .status-pending, .frame-root.dark .status-pending     { --status-bg: #F59E0B; --status-fg: #FFFFFF; }
.dark .frame-root .status-in-progress, .frame-root.dark .status-in-progress { --status-bg: #3171FF; --status-fg: #FFFFFF; }
.dark .frame-root .status-submitted, .frame-root.dark .status-submitted   { --status-bg: #7652B9; --status-fg: #FFFFFF; }
.dark .frame-root .status-in-review, .frame-root.dark .status-in-review   { --status-bg: #EAB308; --status-fg: #FFFFFF; }
.dark .frame-root .status-success, .frame-root.dark .status-success     { --status-bg: #028901; --status-fg: #FFFFFF; }
.dark .frame-root .status-failed, .frame-root.dark .status-failed      { --status-bg: #DC2626; --status-fg: #FFFFFF; }
.dark .frame-root .status-expired, .frame-root.dark .status-expired     { --status-bg: #6B7280; --status-fg: #FFFFFF; }
.frame-root .chat-textarea {
  scrollbar-width: none;
}
.frame-root .chat-textarea::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}
@keyframes frame-typingBounce {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30% { transform: translateY(-5px); opacity: 1; }
}
